import {publishedData} from './site-data.mjs?v=site-data5';
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
export function renderFooter(target,v){const link=(name,url)=>{const a=el('a',name);const u=new URL(url);if(u.protocol!=='https:')throw Error('Invalid footer link');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;};const children=[el('h2',v.title),el('p',v.disclaimer)],legal=el('p','For more information see ');legal.append(link(v.privacyLabel,v.privacyUrl),' and ',link(v.termsLabel,v.termsUrl),'.');children.push(legal,el('p',v.credits+' '+v.thanks));const contact=el('p');contact.append(link(v.contactLabel,v.contactUrl));children.push(contact);if(v.extraLabel&&v.extraUrl){const extra=el('p');extra.append(link(v.extraLabel,v.extraUrl));children.push(extra)}const updated=el('p','Last Update '),time=el('time',new Intl.DateTimeFormat('en-GB',{timeZone:'UTC'}).format(new Date(v.lastUpdate+'T00:00:00Z')));time.dateTime=v.lastUpdate;updated.className='last-update';updated.append(time,'.');children.push(updated);target.replaceChildren(...children);}
if(document.querySelector('.site-footer .footer-copy')){const record=await publishedData('footer');if(record)try{renderFooter(document.querySelector('.site-footer .footer-copy'),record.values)}catch{}}
